fn main() {
    let s = "ab"
    print(str_len(&s))
    let total = 0
    for i in range(0, 3) {
        let t = s
        total = total + str_len(&t)
        drop t
    }
    print(total)
    drop s
}

fn main() {
    let v = push(push(vec(), 1), 2)
    print(len(&v))
    let mut new_v = vec();
    for x in &v {
        new_v = push(new_v, *x)
    }
    print(len(&new_v))
    drop v
    drop new_v
}

struct Bag { items: Vec<Int>, label: Str }

fn main() {
    let b = Bag { items: push(push(vec(), 1), 2), label: "x".to_string() }
    let c = b.clone()
    print(len(&b.items))
    drop b
    print(len(&c.items))
    drop c
}

