struct Bag { items: Vec<Int>, label: Str }

fn main() {
    let v = push(push(vec(), 1), 2)
    let b = Bag { items: clone(&v), label: "hello" }
    print(len(&v))
    drop v
    print(str_len(&b.label))
    drop b
}

fn size(o: Option<Vec<Int>>) -> Int {
    match o {
        Some(&w) => len(&w),
        None => 0,
    }
}

fn main() {
    let v = push(push(vec(), 1), 2);
    let o = Some(v);
    print(len(&v));
    drop v;
    print(size(o));
    drop o;
}

fn main() {
    let s = "hello"
    let v = push(push(vec(), "world"), s)
    print(len(&v))
    drop v
    print(str_len(&s))
    drop s
}

struct Point { x: Int, tag: Str }

fn main() {
    let p = Point { x: 11, tag: "hello" }
    let q = Point { x: 55, ..p }
    print(str_len(&p.tag))
    print(&q.x)
    drop q
    drop p
}

struct Pair { a: Vec<Int>, b: Str }

fn main() {
    let s = Pair { a: push(push(vec(), 1), 2), b: "hello" }
    let Pair { a, b } = s
    print(len(&a))
    drop a
    print(str_len(&b))
    drop b
    print(str_len(&s.b))
    drop s.b
}

fn main() {
    let o = Some(concat("ab", "cd"))
    match o {
        Some(s) => {
            print(str_len(&s) * 5)
            drop s
        },
        None => print(0),
    }
    match clone(&o) {
        Some(s) => {
            print(str_len(&s) * 6)
            drop s
        },
        None => print(0),
    }
    match o {
        Some(_) => {},
        None => {},
    }
    drop o
}

fn main() {
    let s = "ab";
    print(str_len(&s) * 10);
    let i = 0;
    let total = 0;
    while i < 3 {
        let t = s;
        total = total + str_len(&t) * 5;
        drop t;
        i = i + 1;
    }
    drop s;
    print(total);
}

fn total(v: Vec<Int>, flag: Bool) -> Int {
    let w = v
    if flag {
        let r = len(&w) * 10
        drop w
        return r
    }
    drop w
    let u = push(v, 3)
    let r = len(&u) * 20
    drop u
    r
}

fn main() {
    print(total(push(push(vec(), 1), 2), true))
    print(total(push(push(vec(), 1), 2), false))
}

fn f(o: Option<Vec<Int>>) -> Option<Int> {
    let v = o?
    let r = len(&v) * 10 + len(&o?)
    drop v
    Some(r)
}

fn main() {
    match f(Some(push(push(vec(), 1), 2))) {
        Some(n) => print(n),
        None => print(0),
    }
    match f(None) {
        Some(n) => print(n),
        None => print(99),
    }
}

fn main() {
    let s = "hello";
    let n = 5;
    if n > 3 {
        if n > 4 {
            let t = s;
            print(str_len(&t) * 4);
            drop t
        }
        print(str_len(&s) * 6);
    }
    drop s
}

fn main() {
    let acc = range(0, 10);
    print(len(&acc));
    for i in range(0, 3) {
        let grown = push(clone(&acc), i);
        drop(acc); // Ensure the original 'acc' is dropped before the next iteration
        acc = grown; // Reassign 'acc' to the newly created 'grown' vector
    }
    print(len(&acc));
    drop(acc);
}

