    let s = "hello world"
    let n = 42
    let t = s
    print(str_len(&t))
    drop t
    if n > 3 {
        print(str_len(&s))
    }
    drop s
}

fn main() {
    let v = range(0, 10);
    print(len(&v));
    let mut total = 0;
    for x in &v {
        if x > 4 {
            let w = push(clone(&v), *x);
            total = len(&w);
            drop(w);
            break;
        }
    }
    drop(v);
    print(total);
}
